#ifdef DEBUG
#define _GLIBCXX_DEBUG
#endif

#include <bits/stdc++.h>

using namespace std;

typedef long double ld;

#ifdef DEBUG
#define eprintf(...) fprintf(stderr, __VA_ARGS__), fflush(stderr)
#else
#define eprintf(...) ;
#endif

#define sz(x) ((int) (x).size())
#define TASK "text"

const int inf = (int) 1.01e9;
const long long infll = (long long) 1.01e18;
const ld eps = 1e-9;
const ld pi = acos((ld) -1);

#ifdef DEBUG
mt19937 mrand(300); 
#else
mt19937 mrand(chrono::steady_clock::now().time_since_epoch().count()); 
#endif

int getRand(int x) {
  return mrand() % x;
}

void init() {
}

const int maxn = 505;
int n, m, mod;

bool read_input_data() {
  if (scanf("%d%d%d", &n, &m, &mod) < 3) {
    return false;
  }
  return true;
}

int product_mod(int a, int b) {
  return (long long) a * b % mod;
}

void update_mod(int &a, int b) {
  a += b;
  if (a >= mod) a -= mod;
}

int c[maxn][maxn];

struct T {
  int cnt, sum;

  T(): cnt(0), sum(0) {}

  T(int x): cnt(x), sum(0) {}

  T(int c, int s): cnt(c), sum(s) {}

  T operator * (const T &t) const {
    int s = product_mod(cnt, t.sum);
    update_mod(s, product_mod(sum, t.cnt));
    return T(product_mod(cnt, t.cnt), s);
  }

  T operator + (const T &t) const {
    int c = cnt;
    update_mod(c, t.cnt);
    int s = sum;
    update_mod(s, t.sum);
    return T(c, s);
  }
};

T dp[maxn];
T pdp[maxn][maxn];

void process_all() {
  {
    for (int i = 0; i <= m; ++i) {
      c[i][0] = 1;
      for (int j = 1; j <= i; ++j) {
        c[i][j] = c[i - 1][j - 1];
        update_mod(c[i][j], c[i - 1][j]);
      }
    }
  }
  {
    dp[0] = T(1);
    for (int k = 1; k <= m; ++k) {
      auto &current = dp[k];
      current = T(0);
      for (int i = 0; i < k; ++i) {
        auto x = dp[i] * dp[k - i - 1];
        x = x * T(c[k - 1][i]);
        for (int j = 0; j < k; ++j) {
          auto y = x * T(1 + (j == i), abs(i - j));
          current = current + y;
        }
      }
      eprintf("%d %d\n", dp[k].cnt, dp[k].sum);
    }
  }
  for (int i = 0; i <= n; ++i) {
    for (int j = 0; j <= m; ++j) {
      pdp[i][j] = T(0);
    }
  }
  pdp[0][0] = T(1);
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j <= m; ++j) {
      auto current = pdp[i][j];
      if (!current.cnt && !current.sum) continue;
      {
        auto &next = pdp[i + 1][j];
        next = next + current;
      }
      for (int k = 1; j + k <= m && i + k <= n; ++k) {
        auto &next = pdp[min(n, i + k + 1)][j + k];
        next = next + current * dp[k] * T(c[m - j][k]);
      }
    }
  }
  printf("%d\n", pdp[n][m].sum);
}

int main() {
  init();
#ifdef DEBUG
  assert(freopen(TASK ".in", "r", stdin));
  assert(freopen(TASK ".out", "w", stdout));
#endif
  while (read_input_data()) {
    process_all();
#ifdef DEBUG
    eprintf("Time %.2f\n", (double) clock() / CLOCKS_PER_SEC);
#endif
  }
  return 0;
}
